    <env name="DATABASE_URL" value="postgresql://test:test@localhost:5432/app_test?serverVersion=16&charset=utf8"/>
    <env name="MESSENGER_TRANSPORT_DSN" value="in-memory://"/>
    <env name="MAILER_DSN" value="null://null"/>
</php>
