final class QueryCounter implements \Doctrine\DBAL\Logging\Logger
{
    public int $count = 0;

    public function startQuery(string $sql, ?array $params = null, ?array $types = null): void
    {
        $this->count++;
    }

    public function stopQuery(): void {}
}
